def marcar_sentimientos_historicos(apps, schema_editor):
    sentimientos = apps.get_model('core', 'Sentimiento').objects.using(schema_editor.connection.alias)
    duplicados = (sentimientos.order_by().values('id_publicacion_api_id')
                  .annotate(total=models.Count('pk')).filter(total__gt=1)
                  .values('id_publicacion_api_id'))
    sentimientos.filter(
        ~models.Q(polaridad__range=(-1, 1), confianza__range=(0, 1))
        | models.Q(id_publicacion_api_id__in=duplicados)
    ).update(pendiente_revision=True)


def proteger_confianza(apps, schema_editor):
    # Controlar escrituras permite conservar los valores históricos fuera de rango.
    if schema_editor.connection.vendor == 'postgresql':
        schema_editor.execute("""
            CREATE FUNCTION tw_validar_confianza_sentimiento() RETURNS trigger
            LANGUAGE plpgsql AS $$
            BEGIN
                IF TG_OP = 'UPDATE' THEN
                    IF NEW.confianza IS NOT DISTINCT FROM OLD.confianza THEN
                        RETURN NEW;
                    END IF;
                END IF;
                IF NOT (NEW.confianza BETWEEN 0 AND 1) THEN
                    RAISE EXCEPTION 'La confianza del sentimiento debe estar entre 0 y 1.'
                        USING ERRCODE = '23514', CONSTRAINT = 'sentimiento_confianza_rango';
                END IF;
                RETURN NEW;
            END;
            $$
        """)
        schema_editor.execute("""
            CREATE TRIGGER tw_sentimiento_confianza
            BEFORE INSERT OR UPDATE OF confianza ON "Sentimiento"
            FOR EACH ROW EXECUTE FUNCTION tw_validar_confianza_sentimiento()
        """)
    elif schema_editor.connection.vendor == 'sqlite':
        schema_editor.execute("""
            CREATE TRIGGER tw_sentimiento_confianza_alta BEFORE INSERT ON "Sentimiento"
            WHEN NOT (NEW.confianza BETWEEN 0 AND 1)
            BEGIN
                SELECT RAISE(ABORT, 'La confianza del sentimiento debe estar entre 0 y 1.');
            END
        """)
        schema_editor.execute("""
            CREATE TRIGGER tw_sentimiento_confianza_cambio BEFORE UPDATE OF confianza ON "Sentimiento"
            WHEN NEW.confianza IS NOT OLD.confianza AND NOT (NEW.confianza BETWEEN 0 AND 1)
            BEGIN
                SELECT RAISE(ABORT, 'La confianza del sentimiento debe estar entre 0 y 1.');
            END
        """)


def retirar_proteccion_confianza(apps, schema_editor):
    if schema_editor.connection.vendor == 'postgresql':
        schema_editor.execute('DROP TRIGGER tw_sentimiento_confianza ON "Sentimiento"')
        schema_editor.execute('DROP FUNCTION tw_validar_confianza_sentimiento()')
    elif schema_editor.connection.vendor == 'sqlite':
        schema_editor.execute('DROP TRIGGER tw_sentimiento_confianza_cambio')
        schema_editor.execute('DROP TRIGGER tw_sentimiento_confianza_alta')


